-- Finalize canonical tool metadata, write-time normalization and foreign keys.
update public.agi_agents a set meta=a.meta||jsonb_build_object('tool_keys',coalesce((select jsonb_agg(t.tool_key order by t.tool_key) from public.agi_agent_tools t where t.project_id=a.project_id and t.agi_id=a.agi_id),'[]'::jsonb)),updated_at=now() where a.project_id='hocker-one';
do $$ declare t text; begin foreach t in array array['agi_action_queue','agi_agent_tools','agi_agents','agi_chat_messages','agi_chat_threads','agi_error_patterns','agi_feedback','agi_runs','agi_tasks','agi_update_feed'] loop execute format('drop trigger if exists normalize_agi_id_before_write on public.%I',t); execute format('create trigger normalize_agi_id_before_write before insert or update of agi_id on public.%I for each row execute function public.normalize_agi_id_before_write()',t); end loop; end $$;
do $$ begin if not exists(select 1 from pg_constraint where conname='agi_agents_canonical_agi_id_fkey') then alter table public.agi_agents add constraint agi_agents_canonical_agi_id_fkey foreign key(agi_id) references public.agis(id) on update cascade on delete restrict; end if; if not exists(select 1 from pg_constraint where conname='agi_agent_tools_canonical_agi_id_fkey') then alter table public.agi_agent_tools add constraint agi_agent_tools_canonical_agi_id_fkey foreign key(agi_id) references public.agis(id) on update cascade on delete restrict; end if; end $$;
